Reject(() => MediaReview.Parse("/api/v1/daily-metrics?to=2026-11-05", dailyRoot.ToJsonString(), Scope), "daily source date escaped upper bound");
var duplicatedDailyId = Root(new JsonArray(Daily(), Daily(article: ArticleA)));
Reject(() => MediaReview.Parse("/api/v1/daily-metrics", duplicatedDailyId.ToJsonString(), Scope), "duplicate daily id with different dimension was accepted");
var duplicatedDimension = Root(new JsonArray(Daily(), Daily("different-daily-id")));
