Reject(() => MediaReview.Parse("/api/v1/daily-metrics", missingDailyDimension.ToJsonString(), Scope), "daily row omitted the explicit account-versus-article dimension");

var dueRoot = Root(new JsonArray(Due("d1"), Due("d3"), Due("d7")));
