Reject(() => MediaReview.Parse("/api/v1/due-reviews?account_id=" + AccountB, dueRoot.ToJsonString(), Scope), "due review escaped account filter");
Reject(() => MediaReview.Parse("/api/v1/due-reviews", Root(new JsonArray(Due("d1"), Due("d1"))).ToJsonString(), Scope), "duplicate due article/kind was accepted");
Reject(() => MediaReview.Parse("/api/v1/due-reviews", Root(new JsonArray(Due("latest"))).ToJsonString(), Scope), "latest was accepted as a scheduled due kind");
Check(MediaReview.Parse("/api/v1/observations", Root(new JsonArray()).ToJsonString(), Scope).Rows.Count == 0 &&
    MediaReview.Parse("/api/v1/daily-metrics", Root(new JsonArray()).ToJsonString(), Scope).Rows.Count == 0 &&
    MediaReview.Parse("/api/v1/due-reviews", Root(new JsonArray()).ToJsonString(), Scope).Rows.Count == 0,
    "legal empty read arrays were replaced by errors or fabricated rows");

var overviewView = MediaReview.Parse(OverviewPath, OverviewFixture, Scope); var overview = overviewView.Overview!;
Check(overview.Window.From == new DateOnly(2026, 10, 8) && overview.Window.To == new DateOnly(2026, 11, 6) && overview.Window.PreviousFrom == new DateOnly(2026, 9, 8) &&
    overview.Window.PreviousTo == new DateOnly(2026, 10, 7) && overview.Window.Days == 30 && overview.Window.Period == "30d" &&
    overview.Window.Timezone == "Asia/Shanghai" && !overview.Window.TodayIncomplete && overview.Trend.Count == 30 && overview.PublicationTrend.Count == 30,
    "source-derived thirty-day overview window or full trends were shortened, shifted or assigned today");
var accountA = overview.Accounts.Single(row => row.Id == AccountA); var accountB = overview.Accounts.Single(row => row.Id == AccountB);
Check(accountA.PeriodMetrics["reads"].Value == 290 && accountA.Coverage!.Days == 29 && accountA.Coverage.ExpectedDays == 30 && accountA.Coverage.IsPartial &&
    accountA.Coverage.MissingDates.Single() == new DateOnly(2026, 11, 1) && accountA.Coverage.MetricDays["reads"] == 29,
    "account-level increments were double-counted with article rows or missing-day coverage was erased");
Check(!accountA.Comparisons["reads"].Comparable && accountA.Comparisons["reads"].Delta == null && !string.IsNullOrWhiteSpace(accountA.Comparisons["reads"].Reason),
    "partial coverage was shown as a meaningful period comparison");
var readsComparison = accountB.Comparisons["reads"];
Check(accountB.PeriodMetrics["reads"].Value == 60 && accountB.PreviousMetrics["reads"].Value == 150 && readsComparison.Comparable && readsComparison.Current == 60 &&
    readsComparison.Previous == 150 && readsComparison.Delta == -90 && readsComparison.Percent == -60,
    "negative comparable delta or finite percent was rejected or changed");
var zeroComparison = accountB.Comparisons["likes"]; var missingComparison = accountA.Comparisons["impressions"];
Check(zeroComparison.Comparable && zeroComparison.Current == 0 && zeroComparison.Previous == 0 && zeroComparison.Delta == 0 && zeroComparison.Percent == null &&
    zeroComparison.Reason.Contains("真实零", StringComparison.Ordinal) && !missingComparison.Comparable && missingComparison.Current == null && missingComparison.Previous == null &&
    missingComparison.Delta == null && missingComparison.Percent == null && missingComparison.Reason == overview.Data["accounts"]![0]!["comparisons"]!["impressions"]!["reason"]!.GetValue<string>(),
    "real-zero comparison invented a percentage or missing comparison lost its original source reason");
Check(!accountB.Coverage!.IsPartial && accountB.Coverage.Days == 30 && !accountA.PeriodMetrics["impressions"].Present &&
    overview.Cumulative.Metrics["reads"].Value == 42 && overview.Cumulative.Metrics["impressions"].Present && overview.Cumulative.Metrics["impressions"].IsNull,
    "cumulative snapshots were mixed with daily increments or null and absent overview metrics were confused");
Check(overview.TopArticles.Count == 1 && overview.TopArticles.Single().Data["platform"]!.GetValue<string>() == "zhihu" && overview.Accounts.Count == 2 &&
    overview.Trend.All(day => day.Accounts.Any(row => row.AccountId == AccountA)) && overview.PlatformComparison.Count == 2,
    "top platform filter incorrectly removed other accounts, trends or platform summaries");
Check(overview.DueReviews.Count == 9 && overview.DueReviews.GroupBy(row => row.Id).All(group => group.Count() == 3) && overview.AttentionArticles.Count == 3 &&
    overview.MissingArticles.Count > 0 && overview.PublicationTrend.SelectMany(day => day.Accounts).Any(),
    "overview dropped same-article review nodes, missing articles or published trend rows");
var overviewCopy = overview.Data; overviewCopy["window"]!["period"] = "tampered";
var totalsCopy = overview.Totals; totalsCopy["article_count"] = 999;
var seriesCopy = overview.Series; seriesCopy["name"] = "tampered";
var statusCopy = overview.DataStatus; statusCopy["missing_accounts"]!.AsArray().Clear();
Check(overview.Data["window"]!["period"]!.GetValue<string>() == "30d" && overview.Totals["article_count"]!.GetValue<int>() == 3 &&
    overview.Series["name"]!.GetValue<string>() == "保险200篇" && overview.DataStatus["missing_accounts"]!.AsArray().Count == 1,
    "overview metadata properties exposed shared mutable JSON nodes");
BadOverview(root => root["data"]!.AsObject().Remove("cumulative"), "missing required cumulative summary was accepted");
BadOverview(root => root["data"]!["window"]!["period"] = "7d", "overview period disagreed with query");
BadOverview(root => root["data"]!["window"]!["from"] = "2026-10-09", "overview window did not span its declared thirty days");
BadOverview(root => root["data"]!["window"]!["timezone"] = "UTC", "overview timezone changed its day interpretation");
BadOverview(root => root["data"]!["top"]!["limit"] = 5, "overview top metadata disagreed with query limit");
BadOverview(root => root["data"]!["top"]!["platform"] = "toutiao", "overview top platform metadata disagreed with query");
BadOverview(root => root["data"]!["top_articles"]![0]!["platform"] = "toutiao", "top article escaped requested platform");
BadOverview(root => root["data"]!["cumulative"]!["best_article"]!["account_id"] = "foreign-account", "cumulative best article account escaped the returned account scope");
BadOverview(root => root["data"]!["series"]!.AsObject().Remove("highest_recorded"), "missing nullable series highest number was confused with a known null");
var unfilteredTopRoot = OverviewRoot(); unfilteredTopRoot["data"]!["top"]!["platform"] = null;
const string UnfilteredTopPath = "/api/v1/overview?period=30d&top_n=1";
Check(MediaReview.Parse(UnfilteredTopPath, unfilteredTopRoot.ToJsonString(), Scope).Overview!.TopArticles.Single().Id == "article-b",
