unfilteredTopRoot["data"]!["top"]!.AsObject().Remove("platform");
Reject(() => MediaReview.Parse(UnfilteredTopPath, unfilteredTopRoot.ToJsonString(), Scope), "missing nullable top platform metadata was accepted as explicit null");
BadOverview(root => root["data"]!["accounts"]![0]!["comparisons"]!["reads"]!["delta"] = "0", "wrong-type comparison delta was accepted");
BadOverview(root => root["data"]!["accounts"]![1]!["comparisons"]!["reads"]!["percent"] = "NaN", "non-numeric percent was accepted");
