Reject(() => MediaReview.Parse(OverviewPath + "&account_id=" + AccountA, OverviewFixture, Scope), "overview account filter did not constrain present account identities");

var foreign = (JsonObject)observationRoot.DeepClone(); foreign["_local_scope_id"] = "foreign-partition";
Reject(() => MediaReview.Parse("/api/v1/observations", foreign.ToJsonString(), Scope), "foreign workspace source was accepted");
