var escapedRoot = Root(new JsonArray(Observation())); escapedRoot["data"]![0]!["future_payload"] = new string('<', 900000);
var escaped = escapedRoot.ToJsonString(); var semantic = escapedRoot.ToJsonString(new JsonSerializerOptions { Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping });
Check(Encoding.UTF8.GetByteCount(escaped) > 5 * 1024 * 1024 && Encoding.UTF8.GetByteCount(semantic) < 1024 * 1024 &&
    MediaReview.Parse("/api/v1/observations", escaped, Scope).Rows.Count == 1, "local escaping was mistaken for the one-MiB semantic response budget");
var tooLargeSource = Root(new JsonArray(Observation())); tooLargeSource["data"]![0]!["future_payload"] = new string('a', 1024 * 1024);
Reject(() => MediaReview.Parse("/api/v1/observations", tooLargeSource.ToJsonString(), Scope), "semantic response budget silently truncated or ignored source data");
var rootMetadataBudget = Root(new JsonArray()); rootMetadataBudget["future_metadata"] = new string('a', 1024 * 1024);
