Check(rootMetadataBudget.ToJsonString() == rootMetadataBefore, "root metadata budget rejection changed original source fields");
// Synthetic read-only numeric boundary, separate from the source-derived aggregate fixture.
var highRatioRoot = OverviewRoot(); var highRatioFinding = highRatioRoot["data"]!["attention_articles"]![0]!["attention"]!.AsObject();
const double HighRatio = 9_007_199_254_740_991d * 2;
highRatioFinding["kind"] = "up"; highRatioFinding["metric"] = "reads"; highRatioFinding["sample_size"] = 5;
highRatioFinding["median"] = 0.5; highRatioFinding["current"] = 9_007_199_254_740_991L; highRatioFinding["ratio"] = HighRatio;
Check(MediaReview.Parse(OverviewPath, highRatioRoot.ToJsonString(), Scope).Overview!.AttentionArticles[0].Data["attention"]!["ratio"]!.GetValue<double>() == HighRatio,
