var tooLargeCache = Root(new JsonArray()); tooLargeCache["future_cache_metadata"] = new string('a', 8 * 1024 * 1024);
Reject(() => MediaReview.Parse("/api/v1/observations", tooLargeCache.ToJsonString(), Scope), "raw local parsing exceeded the eight-MiB safety ceiling");

Console.WriteLine($"PASS {checks} isolated native media review model checks; exact query contracts, actual-source thirty-day overview, due nodes, metric absence/null/zero, scope, immutable metadata and budgets; no sockets or real user data.");
